/*
 * ESP32 GPIO Control Dashboard
 * Serves a web dashboard with toggle switches to control 4 LEDs.
 */

#include <WiFi.h>
#include <WebServer.h>

const char* ssid     = "ArduSimNet";
const char* password = "simulator";

int ledPins[] = {2, 4, 16, 17};
bool ledStates[] = {false, false, false, false};

WebServer server(80);

String buildDashboard() {
  String html = "<!DOCTYPE html><html><head>";
  html += "<meta name='viewport' content='width=device-width,initial-scale=1'>";
  html += "<meta http-equiv='refresh' content='2'>";
  html += "<title>ESP32 GPIO Control</title>";
  html += "<style>";
  html += "*{box-sizing:border-box;margin:0;padding:0;}";
  html += "body{font-family:Arial,sans-serif;background:#1a1a2e;color:#e0e0e0;text-align:center;min-height:100vh;padding:30px 20px;}";
  html += "h1{color:#00d4ff;margin-bottom:6px;font-size:24px;}";
  html += "p{color:#888;margin-bottom:24px;font-size:14px;}";
  html += ".grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:20px;max-width:960px;margin:0 auto;}";
  html += ".card{background:#16213e;border-radius:16px;padding:24px 20px;border:1px solid #0f3460;display:flex;flex-direction:column;align-items:center;gap:12px;}";
  html += ".dot{width:16px;height:16px;border-radius:50%;display:inline-block;vertical-align:middle;margin-right:6px;}";
  html += ".name{font-size:18px;font-weight:700;}";
  html += ".pin{color:#666;font-size:12px;margin-top:-6px;}";
  html += ".sw{position:relative;width:64px;height:34px;margin-top:8px;}";
  html += ".sw a{display:block;width:64px;height:34px;border-radius:17px;text-decoration:none;position:relative;transition:background 0.3s;}";
  html += ".sw .track{width:64px;height:34px;border-radius:17px;position:relative;}";
  html += ".sw .knob{position:absolute;width:28px;height:28px;border-radius:50%;top:3px;transition:left 0.3s,background 0.3s;}";
  html += ".sw-on .track{background:#00cc66;}";
  html += ".sw-on .knob{left:33px;background:#fff;}";
  html += ".sw-off .track{background:#444;}";
  html += ".sw-off .knob{left:3px;background:#999;}";
  html += ".label{font-size:13px;font-weight:600;margin-top:4px;}";
  html += ".label-on{color:#00ff88;}";
  html += ".label-off{color:#ff4444;}";
  html += "</style></head><body>";
  html += "<h1>ESP32 GPIO Control Dashboard</h1>";
  html += "<p>Toggle each LED switch on/off</p>";
  html += "<div class='grid'>";

  String cl = "#cccccc";
  String nm = "LED";
  for (int i = 0; i < 4; i++) {
    if (i == 0) { cl = "#ff0000"; nm = "RED"; }
    if (i == 1) { cl = "#00cc00"; nm = "GREEN"; }
    if (i == 2) { cl = "#0066ff"; nm = "BLUE"; }
    if (i == 3) { cl = "#ffcc00"; nm = "YELLOW"; }
    html += "<div class='card'>";
    html += "<div class='name'><span class='dot' style='background:" + cl + "'></span>" + nm + "</div>";
    html += "<div class='pin'>GPIO" + String(ledPins[i]) + "</div>";
    if (ledStates[i]) {
      html += "<div class='sw sw-on'><a href='/led" + String(i + 1) + "/off'><div class='track'><div class='knob'></div></div></a></div>";
      html += "<div class='label label-on'>ON</div>";
    } else {
      html += "<div class='sw sw-off'><a href='/led" + String(i + 1) + "/on'><div class='track'><div class='knob'></div></div></a></div>";
      html += "<div class='label label-off'>OFF</div>";
    }
    html += "</div>";
  }

  html += "</div></body></html>";
  return html;
}

void handleRoot() {
  server.send(200, "text/html", buildDashboard());
}

void handleLed1On()  { ledStates[0] = true;  digitalWrite(ledPins[0], HIGH); server.send(200, "text/plain", "LED1 ON");  Serial.println("[GPIO] RED ON"); }
void handleLed1Off() { ledStates[0] = false; digitalWrite(ledPins[0], LOW);  server.send(200, "text/plain", "LED1 OFF"); Serial.println("[GPIO] RED OFF"); }
void handleLed2On()  { ledStates[1] = true;  digitalWrite(ledPins[1], HIGH); server.send(200, "text/plain", "LED2 ON");  Serial.println("[GPIO] GREEN ON"); }
void handleLed2Off() { ledStates[1] = false; digitalWrite(ledPins[1], LOW);  server.send(200, "text/plain", "LED2 OFF"); Serial.println("[GPIO] GREEN OFF"); }
void handleLed3On()  { ledStates[2] = true;  digitalWrite(ledPins[2], HIGH); server.send(200, "text/plain", "LED3 ON");  Serial.println("[GPIO] BLUE ON"); }
void handleLed3Off() { ledStates[2] = false; digitalWrite(ledPins[2], LOW);  server.send(200, "text/plain", "LED3 OFF"); Serial.println("[GPIO] BLUE OFF"); }
void handleLed4On()  { ledStates[3] = true;  digitalWrite(ledPins[3], HIGH); server.send(200, "text/plain", "LED4 ON");  Serial.println("[GPIO] YELLOW ON"); }
void handleLed4Off() { ledStates[3] = false; digitalWrite(ledPins[3], LOW);  server.send(200, "text/plain", "LED4 OFF"); Serial.println("[GPIO] YELLOW OFF"); }

void setup() {
  Serial.begin(115200);
  Serial.println("\n=== ESP32 GPIO Control Dashboard ===");

  for (int i = 0; i < 4; i++) {
    pinMode(ledPins[i], OUTPUT);
    digitalWrite(ledPins[i], LOW);
  }

  Serial.println("Connecting to Wi-Fi...");
  WiFi.begin(ssid, password);
  while (WiFi.status() != WL_CONNECTED) {
    delay(300);
    Serial.print(".");
  }
  Serial.println();
  Serial.print("IP address: ");
  Serial.println(WiFi.localIP());

  server.on("/",          handleRoot);
  server.on("/led1/on",   handleLed1On);
  server.on("/led1/off",  handleLed1Off);
  server.on("/led2/on",   handleLed2On);
  server.on("/led2/off",  handleLed2Off);
  server.on("/led3/on",   handleLed3On);
  server.on("/led3/off",  handleLed3Off);
  server.on("/led4/on",   handleLed4On);
  server.on("/led4/off",  handleLed4Off);

  server.begin();
  Serial.println("HTTP server started!");
}

void loop() {
  server.handleClient();
  delay(500);
}
